import io
import sys
from rich.console import Console
from rich.file_proxy import FileProxy

def test_file_proxy_isatty():
    # Create a console that is NOT a terminal
    console = Console(file=io.StringIO())
    # Wrap sys.stdout with FileProxy
    # We use a mock for sys.stdout that IS a terminal
    class MockFile:
        def isatty(self):
            return True
        def fileno(self):
            return 1
        def write(self, s):
            pass
        def flush(self):
            pass

    mock_stdout = MockFile()
    proxy = FileProxy(console, mock_stdout)

    print(f"Console is_terminal: {console.is_terminal}")
    print(f"Proxy isatty(): {proxy.isatty()}")

    assert console.is_terminal is False
    assert proxy.isatty() is False

if __name__ == "__main__":
    try:
        test_file_proxy_isatty()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

